import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class AK375 {
    public static Scanner scanInput = new Scanner(System.in);
    public String evaluate(int length, String inputStr) {
        StringBuilder nestedSegments = new StringBuilder();
        StringBuilder mainString = new StringBuilder();
        int maxSegmentLength = 0;
        int totalSegments = 0;

        for (int i = 0; i < length; i++) {
            char c = inputStr.charAt(i);
            if (c == '(') {
                nestedSegments.append('_');
                int j = i + 1;
                while (j < length && inputStr.charAt(j) != ')') {
                    nestedSegments.append(inputStr.charAt(j));
                    j++;
                }
                i = j;
            } else if (c == ')') {
                mainString.append('_');
            } else {
                mainString.append(c);
            }
        }

        String[] nestedParts = nestedSegments.toString().split("_");
        List<String> nestedList = new ArrayList<>();
        for (String part : nestedParts) {
            if (part != null && !part.isEmpty()) {
                nestedList.add(part);
            }
        }
        totalSegments = nestedList.size();

        String[] mainParts = mainString.toString().split("_");
        for (String p : mainParts) {
            if (p.length() > maxSegmentLength) {
                maxSegmentLength = p.length();
            }
        }
        return maxSegmentLength + " " + totalSegments;
    }

    public static void main(String[] args) {
        while (scanInput.hasNext()) {
            int n = scanInput.nextInt();
            String s = scanInput.next();
            long startTime = System.currentTimeMillis();
            String result = new AK375().evaluate(n, s);
            long endTime = System.currentTimeMillis();
            System.out.println(result);
        }
    }
}
